function valueAt(value: unknown, path: string): unknown {
  return path.split(".").reduce<unknown>((current, key) => current && typeof current === "object" ? (current as Record<string, unknown>)[key] : undefined, value)
}
function display(value: unknown) { return value == null || value === "" ? "—" : typeof value === "object" ? JSON.stringify(value) : String(value) }
function parseCursor(value?: string) { if (!value) return {}; try { const decoded = JSON.parse(value); return decoded && typeof decoded === "object" ? decoded as Record<string, unknown> : {} } catch { return {} } }
function nextCursor(page: Record<string, unknown>, pagination?: Pagination) {
  if (!pagination) return undefined
  if (pagination.truncatedField && valueAt(page, pagination.truncatedField) !== true) return undefined
  if (pagination.compound) {
    if (pagination.compound.truncatedField && valueAt(page, pagination.compound.truncatedField) !== true) return undefined
    const values = pagination.compound.outputFields.map((field) => valueAt(page, field))
    if (values.every((value) => value == null || value === "")) return undefined
    return JSON.stringify(Object.fromEntries(pagination.compound.inputFields.map((field, index) => [field, values[index]]).filter(([, value]) => value != null)))
  }
  const token = valueAt(page, pagination.outputToken)
  return typeof token === "string" && token ? token : undefined
}
function pageInput(pagination: Pagination | undefined, cursor?: string) {
  if (!pagination || !cursor) return {}
  return pagination.compound ? parseCursor(cursor) : { [pagination.inputToken]: cursor }
}

function useAreaQuery(area: Area, selected: string) {
  return useInfiniteQuery({
    queryKey: ["emulator", "phase-2-resource", area.model, area.operation, selected],
    initialPageParam: undefined as string | undefined,
    enabled: !area.selector || Boolean(selected),
    queryFn: ({ signal, pageParam }) => runEmulatorOperation<Record<string, unknown>>(area.model, area.operation, { ...pageInput(area.pagination, pageParam), ...(area.selector ? { [area.selector.field]: selected } : {}) }, signal),
    getNextPageParam: (page) => nextCursor(page, area.pagination),
  })
}

function ResourceAreaView({ area, onRun, onInspect }: { area: Area; onRun: (operation: Operation) => void; onInspect: (operation: Operation) => void }) {
  const [selected, setSelected] = useState("")
  const [manualValue, setManualValue] = useState("")
  const selectorQuery = useInfiniteQuery({
    queryKey: ["emulator", "phase-2-selector", area.selector?.sourceModel, area.selector?.sourceOperation],
    initialPageParam: undefined as string | undefined,
    enabled: Boolean(area.selector && !area.selector.manual),
    queryFn: ({ signal, pageParam }) => runEmulatorOperation<Record<string, unknown>>(area.selector!.sourceModel, area.selector!.sourceOperation, pageInput(area.selector!.pagination, pageParam), signal),
    getNextPageParam: (page) => nextCursor(page, area.selector?.pagination),
  })
  const options = area.selector && !area.selector.manual ? selectorQuery.data?.pages.flatMap((page) => {
    const values = valueAt(page, area.selector!.responseKey)
    if (!Array.isArray(values)) return []
    return values.map((item) => {
      const record = item && typeof item === "object" ? item as Record<string, unknown> : area.selector!.primitiveField ? { [area.selector!.primitiveField]: item } : undefined
      if (!record) return undefined
      const id = area.selector!.valueField ? valueAt(record, area.selector!.valueField) : area.selector!.primitiveField ? record[area.selector!.primitiveField] : undefined
      const label = area.selector!.labelField ? valueAt(record, area.selector!.labelField) : id
      return typeof id === "string" && id ? { id, label: typeof label === "string" && label ? label : id } : undefined
    }).filter((option): option is { id: string; label: string } => Boolean(option))
  }) ?? [] : []
  const query = useAreaQuery(area, selected)
  const rows = area.responseKeys.flatMap((key) => query.data?.pages.flatMap((page) => {
    const values = valueAt(page, key)
    if (!Array.isArray(values)) return []
    return values.flatMap((item) => {
      if (item && typeof item === "object") return [item as Record<string, unknown>]
      return area.primitiveField ? [{ [area.primitiveField]: item }] : []
    })
  }) ?? [])
  return <div className="mt-3 overflow-hidden rounded-lg border">
    <div className="flex flex-wrap items-center justify-between gap-3 border-b bg-surface-subtle px-4 py-3"><div><h3 className="font-semibold">{area.title}<Badge className="ml-2" variant="secondary">{query.isSuccess ? rows.length : "—"}</Badge></h3><p className="mt-1 text-sm text-muted-foreground">{area.description}</p></div><div className="flex flex-wrap gap-2">{area.actions?.map((action) => <Button key={`${action.model}.${action.operation}`} size="sm" variant="outline" disabled={Boolean(area.selector && !selected)} onClick={() => onRun({ ...action, input: { ...action.input, ...(area.selector ? { [area.selector.field]: selected } : {}) } })}>{action.label}</Button>)}<Button size="sm" variant="outline" disabled={query.isFetching || Boolean(area.selector && !selected)} onClick={() => void query.refetch()}>{query.isFetching ? "Refreshing…" : "Refresh"}</Button></div></div>
    {area.selector && <div className="flex flex-wrap items-end gap-2 border-b bg-background px-4 py-3"><label className="grid min-w-64 max-w-xl flex-1 gap-1.5 text-sm font-medium">{area.selector.label}{area.selector.manual ? <input className="h-9 rounded-md border bg-background px-3 font-normal" value={manualValue} onChange={(event) => setManualValue(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") setSelected(manualValue.trim()) }} placeholder={area.selector.placeholder ?? `Enter ${area.selector.label.toLowerCase()}`} /> : <select className="h-9 rounded-md border bg-background px-3 font-normal" value={selected} onChange={(event) => setSelected(event.target.value)}><option value="">Select {area.selector.label.toLowerCase()}</option>{options.map((option) => <option key={option.id} value={option.id}>{option.label}</option>)}</select>}</label>{area.selector.manual && <Button size="sm" variant="outline" disabled={!manualValue.trim()} onClick={() => setSelected(manualValue.trim())}>Load</Button>}{!area.selector.manual && selectorQuery.hasNextPage && <Button size="sm" variant="outline" disabled={selectorQuery.isFetching} onClick={() => void selectorQuery.fetchNextPage()}>Load more {area.selector.label.toLowerCase()}s</Button>}{!area.selector.manual && selectorQuery.error && <p role="alert" className="mt-2 text-sm text-destructive">{selectorQuery.error.message}</p>}</div>}
    {query.error ? <p role="alert" className="p-4 text-sm text-destructive">{query.error.message}</p> : area.selector && !selected ? <p role="status" className="p-4 text-sm text-muted-foreground">{area.selector.manual ? `Enter a ${area.selector.label.toLowerCase()} to view ${area.title.toLowerCase()}.` : selectorQuery.isPending ? `Loading ${area.selector.label.toLowerCase()}s…` : options.length ? `Select a ${area.selector.label.toLowerCase()} to view ${area.title.toLowerCase()}.` : `No ${area.selector.label.toLowerCase()}s are available in this emulator.`}</p> : query.isPending ? <p role="status" className="p-4 text-sm text-muted-foreground">Loading {area.title.toLowerCase()}…</p> : rows.length === 0 ? <p role="status" className="p-4 text-sm text-muted-foreground">No {area.title.toLowerCase()} found.</p> : <div className="overflow-x-auto"><Table><TableHeader className="bg-surface-subtle"><TableRow>{area.columns.map(([, label]) => <TableHead key={label}>{label}</TableHead>)}{area.detail || area.rowActions?.length ? <TableHead>Actions</TableHead> : null}</TableRow></TableHeader><TableBody>{rows.map((row, index) => { const key = display(row.Id ?? row.id ?? row.arn ?? row.Arn ?? row.Name ?? row.name ?? row.DomainName ?? row.connectionId ?? row.virtualInterfaceId ?? row.linkId ?? index); return <TableRow key={`${key}:${index}`}>{area.columns.map(([field]) => <TableCell key={field} className="max-w-72 truncate">{display(valueAt(row, field))}</TableCell>)}{area.detail || area.rowActions?.length ? <TableCell><div className="flex flex-wrap gap-1">{area.detail && <Button size="xs" variant="outline" onClick={() => onInspect({ model: area.model, operation: area.detail!.operation, label: `${area.title} details`, input: { ...area.detail!.input(row), ...(area.selector ? { [area.selector.field]: selected } : {}) } })}>Details</Button>}{area.rowActions?.map((action) => <Button key={action.operation} size="xs" variant={/^(Delete|Deregister|Stop|Disable|Revoke)/.test(action.operation) ? "destructive" : "outline"} onClick={() => onRun({ model: area.model, operation: action.operation, label: action.label, input: { ...action.input(row), ...(area.selector ? { [area.selector.field]: selected } : {}) } })}>{action.label}</Button>)}</div></TableCell> : null}</TableRow>})}</TableBody></Table></div>}
    {selectorQuery.hasNextPage && area.selector && <div className="border-t p-3"><Button size="sm" variant="outline" disabled={selectorQuery.isFetching} onClick={() => void selectorQuery.fetchNextPage()}>Load more options</Button></div>}
    {query.hasNextPage && <div className="border-t p-3"><Button size="sm" variant="outline" disabled={query.isFetching} onClick={() => void query.fetchNextPage()}>{query.isFetchingNextPage ? "Loading more…" : "Load more"}</Button></div>}
  </div>
}

export function Phase2ServiceConsole({ service }: { service: Phase2Service }) {
  const [selection, setSelection] = useState<Operation>()
  const [inspection, setInspection] = useState<Operation>()
  const entry = findCatalogService(service)
  const definition = definitions[service]
  const inspectionQuery = useQuery({ queryKey: ["emulator", "phase-2-detail", inspection?.model, inspection?.operation, JSON.stringify(inspection?.input ?? {})], queryFn: ({ signal }) => inspection ? runEmulatorOperation(inspection.model, inspection.operation, inspection.input ?? {}, signal) : Promise.resolve(undefined), enabled: Boolean(inspection) })
  if (!entry) return null
  const run = (operation: Operation) => { setInspection(undefined); setSelection(operation) }
  const inspect = (operation: Operation) => { setSelection(undefined); setInspection(operation) }
  return <>
    <section className="flex flex-wrap items-center gap-3.5"><ServiceIcon id={service} className="size-10" /><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><h1 className="text-[1.75rem] leading-tight font-semibold tracking-tight">{entry.name}</h1><Badge variant="secondary">Local emulator</Badge></div><p className="mt-1 max-w-4xl text-sm text-muted-foreground">{definition.description}</p></div></section>
    <Card className="gap-0 rounded-xl border py-0 ring-0"><CardHeader className="border-b bg-surface-subtle px-4 py-3.5 sm:px-5"><h2 className="text-lg font-semibold">Local resources</h2><p className="text-sm text-muted-foreground">Read operations are run against the configured emulator. Resource actions are limited to operations with implemented handlers.</p></CardHeader><CardContent className="p-4 sm:p-5"><Tabs defaultValue={definition.areas[0]?.id}><TabsList className="h-auto w-full max-w-full flex-wrap justify-start overflow-visible">{definition.areas.map((area) => <TabsTrigger key={area.id} value={area.id} className="flex-none">{area.title}</TabsTrigger>)}</TabsList>{definition.areas.map((area) => <TabsContent key={area.id} value={area.id}><ResourceAreaView area={area} onRun={run} onInspect={inspect} /></TabsContent>)}</Tabs></CardContent></Card>
    {inspection && <Card className="gap-0 rounded-xl border py-0 ring-0"><CardHeader className="flex flex-wrap items-center justify-between gap-3 border-b bg-surface-subtle px-4 py-3.5 sm:px-5"><div><h2 className="text-lg font-semibold">{inspection.label}</h2><p className="mt-1 font-mono text-xs text-muted-foreground">{inspection.model}.{inspection.operation}</p></div><div className="flex gap-2"><Button variant="outline" size="sm" disabled={inspectionQuery.isFetching} onClick={() => void inspectionQuery.refetch()}>Refresh details</Button><Button variant="ghost" size="sm" onClick={() => setInspection(undefined)}>Close</Button></div></CardHeader><CardContent className="p-4 sm:p-5">{inspectionQuery.error ? <p role="alert" className="text-sm text-destructive">{inspectionQuery.error.message}</p> : inspectionQuery.isPending ? <p role="status" className="text-sm text-muted-foreground">Loading details…</p> : <ResourceDetailView value={inspectionQuery.data} />}</CardContent></Card>}
    <section aria-label={`${entry.name} console sections`} className="grid gap-4 lg:grid-cols-3">{definition.sections.map((section) => <Card key={section.title} className="gap-0 rounded-xl border py-0 ring-0"><CardHeader className="border-b bg-surface-subtle px-4 py-3.5"><h2 className="text-base font-semibold">{section.title}</h2><p className="text-sm leading-5 text-muted-foreground">{section.description}</p></CardHeader><CardContent className="flex flex-wrap gap-2 p-4">{section.actions.map((action) => <Button key={`${action.model}.${action.operation}`} type="button" size="sm" variant="outline" onClick={() => run(action)}>{action.label}</Button>)}</CardContent></Card>)}</section>
    <ApiOperationExplorer key={`${service}:${selection?.model ?? "all"}:${selection?.operation ?? ""}:${JSON.stringify(selection?.input ?? {})}`} service={service} initialModel={selection?.model} initialOperation={selection?.operation} initialValues={selection?.input} startExpanded={Boolean(selection)} />
    <p className="text-xs text-muted-foreground">Requests run against the configured local emulator. The API operation explorer marks emulator stubs, missing handlers, and SDK command gaps explicitly.</p>
  </>
}
